private void enlarge(final int size) {
    // Ensure the internal byte array can accommodate the current length plus the requested size.
    int currentLength = this.length; // current number of bytes stored
    int currentCapacity = this.buffer.length;
    int requiredCapacity = currentLength + size;

    if (requiredCapacity <= currentCapacity) {
        return; // no need to enlarge
    }

    // Double the capacity or set to required capacity, whichever is larger.
    int newCapacity = Math.max(currentCapacity * 2, requiredCapacity);
    byte[] newBuffer = new byte[newCapacity];
    System.arraycopy(this.buffer, 0, newBuffer, 0, currentLength);
    this.buffer = newBuffer;
}

